codeExample.bad:
/* Input border #A6A6A6 on white #FFFFFF background is only 2.43:1 -- fails the 3:1 minimum, so the field's edges are hard to locate */
.text-input {
  border: 1px solid #A6A6A6;
  background-color: #FFFFFF;
  padding: 8px;
}

codeExample.good:
/* Input border #767676 on white #FFFFFF background is 4.54:1 -- passes the 3:1 minimum, so the field boundary is clearly visible */
.text-input {
  border: 1px solid #767676;
  background-color: #FFFFFF;
  padding: 8px;
}
